:root {
  --bg-card: #f2ead8;
  --bg-header: #3b2a14;
  --bg-rank: #e8dfc8;
  --bg-rank-alt: #ddd3b8;
  --bg-footer: #2e1f0e;
  --pipe-col-1: #b08040;
  --pipe-col-2: #8aac6e;
  --pipe-col-3: #c0724a;
  --pipe-shadow: #7a5c2a;
  --text-light: #f5edd8;
  --text-dark: #2a1a08;
  --text-mid: #5c3e1c;
  --text-muted: #9a7d52;
  --status-voiced: #4a7c3f;
  --status-voiced-bg: #d4edcc;
  --status-partial: #7a6120;
  --status-partial-bg: #f0e4a0;
  --status-pending: #7a3030;
  --status-pending-bg: #f0d0c8;
  --border-main: #8a6a38;
  --border-light: #c4a870;
  --accent-gold: #c8960c;
}

article.organ-card {
  width: 480px;
  background: var(--bg-card);
  border: 3px solid var(--border-main);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  padding: 10px 16px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  border-bottom: 3px solid var(--accent-gold);
}

.workshop-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.card-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-light);
  margin: 0;
  letter-spacing: 1px;
}

.card-date {
  font-size: 11px;
  color: var(--text-muted);
  letter-spacing: 1px;
}

.organ-body {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0;
}

.pipe-rank {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px;
  border-bottom: 1px solid var(--border-light);
}

.pipe-rank:nth-child(even) {
  background: var(--bg-rank-alt);
}

.pipe-rank:nth-child(odd) {
  background: var(--bg-rank);
}

.rank-meta {
  display: flex;
  flex-direction: column;
  width: 110px;
  flex-shrink: 0;
}

.rank-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-dark);
  line-height: 1.2;
}

.rank-pitch {
  font-size: 12px;
  color: var(--text-mid);
  font-weight: 600;
}

.pipe-bars {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  flex: 1;
  height: 38px;
}

.pipe {
  flex: 1;
  border-radius: 2px 2px 0 0;
  border-top: 2px solid var(--pipe-shadow);
}

.pipe-rank:nth-child(1) .pipe { background: var(--pipe-col-1); }
.pipe-rank:nth-child(2) .pipe { background: var(--pipe-col-2); }
.pipe-rank:nth-child(3) .pipe { background: var(--pipe-col-3); }

.pipe-rank:nth-child(1) .pipe.p1 { height: 34px; }
.pipe-rank:nth-child(1) .pipe.p2 { height: 28px; }
.pipe-rank:nth-child(1) .pipe.p3 { height: 38px; }
.pipe-rank:nth-child(1) .pipe.p4 { height: 22px; }
.pipe-rank:nth-child(1) .pipe.p5 { height: 32px; }
.pipe-rank:nth-child(1) .pipe.p6 { height: 18px; }
.pipe-rank:nth-child(1) .pipe.p7 { height: 26px; }

.pipe-rank:nth-child(2) .pipe.p1 { height: 20px; }
.pipe-rank:nth-child(2) .pipe.p2 { height: 36px; }
.pipe-rank:nth-child(2) .pipe.p3 { height: 24px; }
.pipe-rank:nth-child(2) .pipe.p4 { height: 38px; }
.pipe-rank:nth-child(2) .pipe.p5 { height: 16px; }
.pipe-rank:nth-child(2) .pipe.p6 { height: 30px; }
.pipe-rank:nth-child(2) .pipe.p7 { height: 22px; }

.pipe-rank:nth-child(3) .pipe.p1 { height: 38px; }
.pipe-rank:nth-child(3) .pipe.p2 { height: 18px; }
.pipe-rank:nth-child(3) .pipe.p3 { height: 30px; }
.pipe-rank:nth-child(3) .pipe.p4 { height: 24px; }
.pipe-rank:nth-child(3) .pipe.p5 { height: 36px; }
.pipe-rank:nth-child(3) .pipe.p6 { height: 20px; }
.pipe-rank:nth-child(3) .pipe.p7 { height: 28px; }

.rank-status {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 3px 8px;
  border-radius: 10px;
  flex-shrink: 0;
  text-transform: uppercase;
}

.status-voiced {
  color: var(--status-voiced);
  background: var(--status-voiced-bg);
  border: 1px solid var(--status-voiced);
}

.status-partial {
  color: var(--status-partial);
  background: var(--status-partial-bg);
  border: 1px solid var(--status-partial);
}

.status-pending {
  color: var(--status-pending);
  background: var(--status-pending-bg);
  border: 1px solid var(--status-pending);
}

.card-footer {
  background: var(--bg-footer);
  padding: 8px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-top: 3px solid var(--accent-gold);
}

.footer-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  flex: 1;
}

.footer-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.footer-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-light);
}

.divider-v {
  width: 1px;
  height: 28px;
  background: var(--border-main);
  flex-shrink: 0;
}
